B.a2c=new A.an(B.cP,["Seviye 25","80 Kalas & Ta\u015f","0.18 Alt\u0131n & Ta\xe7 / sn","\xc7\xf6l Karosu"],t.w)
B.a_o=s(["Karakum Diyar\u0131nda kervansaray gelirleri 2 kat\u0131na (2x) \xe7\u0131kar."],t.s)
B.VF=s(["Caravanserai revenue is doubled in the Karakum Realm."],t.s)
B.Z5=s(["kervansaray","han","ipekyolu","ticaret","alt\u0131n","ta\xe7","caravanserai","desert"],t.s)
B.Ri=new A.bx("bld_caravanserai",B.at,"\u0130pek Yolu Kervansaray\u0131 (Han)","Silk Road Caravanserai (Inn)","\xc7\xf6l ticaret yollar\u0131 \xfczerinde dinlenen t\xfcccarlardan Alt\u0131n, Ta\xe7 ve egzotik gelir sa\u011flar.","Houses traveling merchants to generate Gold, Crowns, and exotic revenue.","Kervansaray, \xc7\xf6l karolar\u0131na in\u015fa edilir. Saniyede 0.18 alt\u0131n ve refah \xfcretir. Kervan rotalar\u0131n\u0131n kesi\u015fim noktas\u0131na kuruldu\u011funda ticaret rezonans\u0131n\u0131 katlayarak b\xfcy\xfck miktarda Ta\xe7 ve Kut kazand\u0131r\u0131r.","Generates 0.18 Gold/sec. Amplifies trade resonance when connected to multiple caravan routes.",B.SN,B.p,"SV.25 | \xc7\xd6L",B.a2c,B.I,B.I,B.a_o,B.VF,B.Z5)
